package gateway

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"strconv"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/gorilla/websocket"
)

const relayFakeProxy403Body = "<!DOCTYPE html><html><head><title>ERROR: The requested URL could not be retrieved</title>" +
	"</head><body><p>Unable to determine IP address from host name (ERR_DNS_FAIL)</p>" +
	"<p>Generated by egress-proxy (squid/6.10)</p></body></html>"

// Scripted HTTP answer of a connector route, a nil spec meaning the success answer
type relayFakeSpec struct {
	status  int
	headers map[string]string
	body    string
}

// Builds the scripted answer from the bearer the request carried
type relayFakeScript func(token string) *relayFakeSpec

func relayFixed(spec *relayFakeSpec) relayFakeScript {
	return func(string) *relayFakeSpec { return spec }
}

// An egress proxy refusing on its own with an HTML page and proxy headers
func relayProxy403() relayFakeScript {
	return relayFixed(&relayFakeSpec{status: 403, headers: map[string]string{"Server": "squid/6.10", "X-Squid-Error": "ERR_DNS_FAIL 0",
		"Via": "1.1 egress-proxy (squid/6.10)", "Content-Type": "text/html;charset=utf-8"}, body: relayFakeProxy403Body})
}

// A refusal the connector itself authored as a JSON error object
func relayRefusal(status int, reason string) relayFakeScript {
	body, _ := json.Marshal(map[string]any{"error": reason})
	return relayFixed(&relayFakeSpec{status: status, headers: map[string]string{"Content-Type": "application/json"}, body: string(body)})
}

// A JSON emitting hop refusing on its own, named by a response header
func relayJSONProxy403(headers map[string]string) relayFakeScript {
	h := map[string]string{"Content-Type": "application/json"}
	for k, v := range headers {
		h[k] = v
	}
	return relayFixed(&relayFakeSpec{status: 403, headers: h, body: `{"error": "upstream dns timeout"}`})
}

// A hop echoing the request bearer into its body
func relayEchoing(status int, template string) relayFakeScript {
	return func(token string) *relayFakeSpec {
		return &relayFakeSpec{status: status, headers: map[string]string{"Content-Type": "application/json"}, body: strings.ReplaceAll(template, "{token}", token)}
	}
}

// Loopback connector with a real websocket relay route and scripted provision and media routes
type relayFakeConn struct {
	t              *testing.T
	srv            *httptest.Server
	mu             sync.Mutex
	platform       string
	secret         string
	gatewayID      string
	provisionCalls int
	mediaCalls     int
	provision      []relayFakeScript
	media          []relayFakeScript
	bearersSeen    []string
	wsAuth         []string
	outbound       []map[string]any
	unackedOps     map[string]bool
	droppingOps    map[string]bool
	identityToken  string
	url            string
}

func newRelayFakeConn(t *testing.T) *relayFakeConn {
	t.Helper()
	c := &relayFakeConn{t: t, platform: "slack", unackedOps: map[string]bool{}, droppingOps: map[string]bool{},
		identityToken: "nas-identity-token-must-never-be-logged"}
	upgrader := websocket.Upgrader{}
	c.srv = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch r.URL.Path {
		case "/relay":
			ws, err := upgrader.Upgrade(w, r, nil)
			if err != nil {
				return
			}
			c.handleWS(ws, r.Header.Get("Authorization"))
		case "/access-token":
			c.mu.Lock()
			tok := c.identityToken
			c.mu.Unlock()
			io.WriteString(w, tok)
		case "/relay/provision":
			c.provisionRoute(w, r)
		case "/relay/media":
			c.mediaRoute(w, r)
		default:
			t.Errorf("unexpected connector route %s", r.URL.Path)
			w.WriteHeader(404)
		}
	}))
	t.Cleanup(c.srv.Close)
	c.url = "ws" + strings.TrimPrefix(c.srv.URL, "http") + "/relay"
	return c
}

// Points the relay URL and the identity endpoint at the fake
func (c *relayFakeConn) install(t *testing.T) {
	t.Helper()
	t.Setenv("GATEWAY_RELAY_URL", c.url)
	t.Setenv("GATEWAY_RELAY_IDP_TOKEN_URL", c.srv.URL+"/access-token")
}

// Whether the bearer is an upgrade token of the issued gateway id and secret
func (c *relayFakeConn) bearerValid(header string) bool {
	c.mu.Lock()
	secret, gatewayID := c.secret, c.gatewayID
	c.mu.Unlock()
	if secret == "" || !strings.HasPrefix(header, "Bearer ") {
		return false
	}
	raw, err := base64.RawURLEncoding.DecodeString(strings.TrimRight(header[len("Bearer "):], "="))
	if err != nil {
		return false
	}
	parts := strings.Split(string(raw), ":")
	if len(parts) < 3 {
		return false
	}
	sig := parts[len(parts)-1]
	exp := parts[len(parts)-2]
	payload := strings.Join(parts[:len(parts)-2], ":")
	mac := hmac.New(sha256.New, []byte(secret))
	mac.Write([]byte(payload + ":" + exp))
	return payload == gatewayID && hmac.Equal([]byte(hex.EncodeToString(mac.Sum(nil))), []byte(sig))
}

func (c *relayFakeConn) handleWS(ws *websocket.Conn, auth string) {
	defer ws.Close()
	if !c.bearerValid(auth) {
		c.mu.Lock()
		c.wsAuth = append(c.wsAuth, "rejected")
		c.mu.Unlock()
		ws.WriteControl(websocket.CloseMessage, websocket.FormatCloseMessage(4401, "unauthorized"), timeNowPlusSecond())
		ws.ReadMessage()
		return
	}
	c.mu.Lock()
	c.wsAuth = append(c.wsAuth, "ok")
	c.mu.Unlock()
	for {
		_, data, err := ws.ReadMessage()
		if err != nil {
			return
		}
		for _, line := range strings.Split(string(data), "\n") {
			if strings.TrimSpace(line) == "" {
				continue
			}
			var frame map[string]any
			if json.Unmarshal([]byte(line), &frame) != nil {
				continue
			}
			if !c.onFrame(ws, frame) {
				return
			}
		}
	}
}

// Answers hello with a descriptor and outbound with a success result, false once the socket was dropped
func (c *relayFakeConn) onFrame(ws *websocket.Conn, frame map[string]any) bool {
	switch frame["type"] {
	case "hello":
		platform, _ := frame["platform"].(string)
		if platform == "" {
			platform = c.platform
		}
		descriptor := map[string]any{"contract_version": 1, "platform": platform, "label": "Slack", "max_message_length": 4000,
			"supports_draft_streaming": false, "supports_edit": true, "supports_threads": true, "markdown_dialect": "slack_mrkdwn",
			"len_unit": "chars", "supported_ops": []any{"send", "edit", "typing", "send_media"}}
		out, _ := json.Marshal(map[string]any{"type": "descriptor", "descriptor": descriptor})
		ws.WriteMessage(websocket.TextMessage, append(out, '\n'))
	case "outbound":
		action, _ := frame["action"].(map[string]any)
		op, _ := action["op"].(string)
		c.mu.Lock()
		c.outbound = append(c.outbound, action)
		n := len(c.outbound)
		unacked, dropping := c.unackedOps[op], c.droppingOps[op]
		c.mu.Unlock()
		if unacked {
			return true
		}
		if dropping {
			ws.WriteControl(websocket.CloseMessage, websocket.FormatCloseMessage(1000, ""), timeNowPlusSecond())
			return false
		}
		out, _ := json.Marshal(map[string]any{"type": "outbound_result", "requestId": frame["requestId"],
			"result": map[string]any{"success": true, "message_id": "ts-" + strconv.Itoa(n)}})
		ws.WriteMessage(websocket.TextMessage, append(out, '\n'))
	}
	return true
}

// Outbound actions of one op
func (c *relayFakeConn) ops(op string) []map[string]any {
	c.mu.Lock()
	defer c.mu.Unlock()
	var out []map[string]any
	for _, a := range c.outbound {
		if a["op"] == op {
			out = append(out, a)
		}
	}
	return out
}

// Next scripted answer of a route, nil meaning success
func (c *relayFakeConn) next(script *[]relayFakeScript, auth string) *relayFakeSpec {
	if len(*script) == 0 {
		return nil
	}
	spec := (*script)[0]
	*script = (*script)[1:]
	return spec(strings.TrimPrefix(auth, "Bearer "))
}

func relayWriteSpec(w http.ResponseWriter, spec *relayFakeSpec) {
	for k, v := range spec.headers {
		w.Header().Set(k, v)
	}
	w.WriteHeader(spec.status)
	io.WriteString(w, spec.body)
}

func (c *relayFakeConn) provisionRoute(w http.ResponseWriter, r *http.Request) {
	auth := r.Header.Get("Authorization")
	raw, _ := io.ReadAll(r.Body)
	c.mu.Lock()
	c.bearersSeen = append(c.bearersSeen, auth)
	c.provisionCalls++
	spec := c.next(&c.provision, auth)
	if spec != nil {
		c.mu.Unlock()
		relayWriteSpec(w, spec)
		return
	}
	var body map[string]any
	json.Unmarshal(raw, &body)
	c.gatewayID, _ = body["gatewayId"].(string)
	if c.secret == "" {
		c.secret = strings.Repeat("s", 64)
	}
	routeKeys := body["routeKeys"]
	if routeKeys == nil {
		routeKeys = []any{}
	}
	out, _ := json.Marshal(map[string]any{"secret": c.secret, "deliveryKey": strings.Repeat("d", 64), "tenant": "tenant-ops",
		"gatewayId": c.gatewayID, "routeKeys": routeKeys})
	c.mu.Unlock()
	w.Header().Set("Content-Type", "application/json")
	w.Write(out)
}

func (c *relayFakeConn) mediaRoute(w http.ResponseWriter, r *http.Request) {
	auth := r.Header.Get("Authorization")
	io.ReadAll(r.Body)
	c.mu.Lock()
	c.bearersSeen = append(c.bearersSeen, auth)
	c.mediaCalls++
	n := c.mediaCalls
	spec := c.next(&c.media, auth)
	c.mu.Unlock()
	if spec != nil {
		relayWriteSpec(w, spec)
		return
	}
	if !c.bearerValid(auth) {
		relayWriteSpec(w, relayRefusal(401, "unauthenticated; per-gateway bearer required")(""))
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(201)
	out, _ := json.Marshal(map[string]any{"id": "m-" + strconv.Itoa(n), "size": 1})
	w.Write(out)
}

// Control frame write deadline of the fake connector
func timeNowPlusSecond() time.Time { return time.Now().Add(time.Second) }
